// One row per domain you send email from. Replace these with your own,
// or swap this node for a Google Sheets "Get rows" node with the same columns.
// dkim_selectors: the s= value in the DKIM-Signature header of a real email from that domain.
return [
  { json: { domain: 'negozio-online.org', label: 'root domain, mailboxes', dkim_selectors: [] } },
  { json: { domain: 'send.negozio-online.org', label: 'marketing sending subdomain', dkim_selectors: ['s1', 's2'] } },
];

// Reads the public DNS records that authenticate email for one domain.
// Uses a public DNS service over HTTPS: no credentials, same answers as nslookup.
const domain = String($json.domain || '').trim().toLowerCase().replace(/\.$/, '');
const http = (url) => this.helpers.httpRequest({ method: 'GET', url, json: true });
const errors = [];

// One DNS question. Returns the answer strings, [] when nothing is published, null when the lookup failed.
async function ask(name, type) {
  try {
    const res = await http('https://dns.google/resolve?name=' + encodeURIComponent(name) + '&type=' + type);
    if (res.Status !== 0 && res.Status !== 3) throw new Error('DNS status ' + res.Status);
    const wanted = type === 'MX' ? 15 : 16;
    return (res.Answer || [])
      .filter((a) => a.type === wanted)
      .map((a) => String(a.data).replace(/"\s*"/g, '').replace(/^"|"$/g, '').trim());
  } catch (err) {
    errors.push(type + ' ' + name + ': ' + (err.message || err));
    return null;
  }
}

// SPF: follow every include and redirect, counting DNS lookups (the standard allows 10).
const spfRecords = [];
const spfIncludes = []; // named in the domain's own record
const spfTree = []; // every include and redirect in the whole tree
let spfLookups = 0;
let spfExact = true;
const fetched = new Map();

async function walkSpf(name, path) {
  if (path.includes(name) || spfLookups > 40) return; // a loop, or a record far past any limit
  const top = path.length === 0;
  if (!fetched.has(name)) {
    const before = errors.length;
    const answers = await ask(name, 'TXT');
    if (answers === null && !top) errors.length = before; // a broken include is not a failure of the whole check
    fetched.set(name, answers);
  }
  const answers = fetched.get(name);
  if (answers === null) {
    spfExact = false;
    return;
  }
  const records = answers.filter((t) => /^v=spf1(\s|$)/i.test(t));
  if (top) spfRecords.push(...records);
  if (records.length !== 1) return;
  for (const raw of records[0].split(/\s+/).slice(1)) {
    const term = raw.replace(/^[+\-~?]/, '').toLowerCase();
    const target = (term.match(/^(?:include:|redirect=)(.+)$/) || [])[1];
    if (target) {
      spfLookups += 1;
      if (top) spfIncludes.push(target);
      spfTree.push(target);
      if (target.includes('%{')) spfExact = false; // a macro cannot be followed from outside
      else await walkSpf(target, [...path, name]);
    } else if (/^(a|mx|ptr)([:\/]|$)/.test(term) || term.startsWith('exists:')) {
      spfLookups += 1;
    }
  }
}
await walkSpf(domain, []);

// DMARC lives at _dmarc.<domain>. A subdomain without its own record inherits from the closest parent that has one.
const isDmarc = (t) => /^v=dmarc1(\s|;|$)/i.test(t);
let dmarcName = '_dmarc.' + domain;
let dmarcTxt = await ask(dmarcName, 'TXT');
const ownTxt = dmarcTxt || [];
let inherited = false;
const labels = domain.split('.');
for (let i = 1; dmarcTxt && !dmarcTxt.some(isDmarc) && labels.length - i >= 2; i++) {
  const parent = labels.slice(i).join('.');
  const parentTxt = await ask('_dmarc.' + parent, 'TXT');
  if (parentTxt && parentTxt.some(isDmarc)) {
    dmarcTxt = parentTxt;
    dmarcName = '_dmarc.' + parent;
    inherited = true;
  }
}

const mx = await ask(domain, 'MX');

// DKIM keys can only be found by selector name (the s= value in a real email's DKIM-Signature header).
const dkim = [];
for (const selector of $json.dkim_selectors || []) {
  const before = errors.length;
  const answers = await ask(selector + '._domainkey.' + domain, 'TXT');
  if (answers === null) {
    errors.length = before;
    continue;
  }
  const key = answers.find((t) => /(^|;)\s*p=/i.test(t));
  dkim.push({ selector, found: Boolean(key), revoked: Boolean(key) && /(^|;)\s*p=\s*(;|$)/i.test(key) });
}

return {
  json: {
    domain,
    label: $json.label || '',
    checked_at: new Date().toISOString(),
    spf_records: spfRecords,
    spf_lookups: spfLookups,
    spf_lookups_exact: spfExact,
    spf_includes: spfIncludes,
    spf_tree: [...new Set(spfTree)],
    dmarc_records: (dmarcTxt || []).filter(isDmarc),
    dmarc_other_txt: inherited ? [] : ownTxt.filter((t) => !isDmarc(t)),
    dmarc_name: dmarcName,
    dmarc_inherited: inherited,
    mx: mx || [],
    dkim,
    lookup_errors: errors,
  },
};

// Fixed rules, no AI: each finding says what is wrong, what it means in plain words, and how to fix it.
const d = $json;
const findings = [];
const add = (code, level, issue, plain, fix) => findings.push({ code, level, issue, plain, fix });

// Which mailbox provider receives email for this domain (from the MX records).
const MAILBOXES = [
  ['protection.outlook.com', 'Microsoft 365'], ['mx.microsoft', 'Microsoft 365'], ['google.com', 'Google Workspace'], ['googlemail.com', 'Google Workspace'],
  ['pphosted.com', 'Proofpoint'], ['ppe-hosted.com', 'Proofpoint'], ['mimecast', 'Mimecast'], ['iphmx.com', 'Cisco Secure Email'],
  ['messagelabs.com', 'Symantec Email Security'], ['barracudanetworks.com', 'Barracuda'], ['trendmicro', 'Trend Micro'],
  ['hornetsecurity.com', 'Hornetsecurity'], ['esvacloud.com', 'Libraesva'], ['mx.cloudflare.net', 'Cloudflare Email Routing'],
];
// Which email tools the SPF record authorises to send as this domain.
const SENDERS = [
  ['spf.protection.outlook.com', 'Microsoft 365'], ['_spf.google.com', 'Google Workspace'], ['hubspotemail.net', 'HubSpot'],
  ['_spf.salesforce.com', 'Salesforce'], ['pardot.com', 'Salesforce Account Engagement'], ['mktomail.com', 'Marketo'],
  ['servers.mcsv.net', 'Mailchimp'], ['mandrillapp.com', 'Mailchimp Transactional'], ['sendgrid.net', 'SendGrid'],
  ['mailgun.org', 'Mailgun'], ['amazonses.com', 'Amazon SES'], ['sendinblue.com', 'Brevo'], ['brevo.com', 'Brevo'],
  ['mailjet.com', 'Mailjet'], ['mtasv.net', 'Postmark'], ['zendesk.com', 'Zendesk'], ['freshdesk.com', 'Freshdesk'],
  ['musvc.com', 'MailUp'], ['magnews.net', 'MagNews'], ['customerly.io', 'Customerly'], ['docebosaas.com', 'Docebo'],
  ['successfactors.com', 'SAP SuccessFactors'], ['sapsf.eu', 'SAP SuccessFactors'], ['knowbe4.com', 'KnowBe4'],
  ['pphosted.com', 'Proofpoint'], ['ppe-hosted.com', 'Proofpoint'], ['mimecast', 'Mimecast'], ['trendmicro', 'Trend Micro'],
  ['mx.cloudflare.net', 'Cloudflare Email Routing'],
];
const nameOf = (table, host) => (table.find(([needle]) => host.includes(needle)) || [])[1];

const realMx = d.mx.filter((m) => !/^0\s+\.?$/.test(m));
const mxHost = realMx.length ? realMx[0].split(/\s+/).pop().replace(/\.$/, '').toLowerCase() : '';
const mailbox = mxHost ? nameOf(MAILBOXES, mxHost) || mxHost.split('.').slice(-2).join('.') : 'none';
const senders = [...new Set(d.spf_tree.map((h) => nameOf(SENDERS, h)).filter(Boolean))]; // the whole include tree
const otherIncludes = d.spf_includes.filter((h) => !nameOf(SENDERS, h));

// ---- SPF: which servers may send for this domain ----
const spf = d.spf_records[0] || '';
if (d.spf_records.length > 1) {
  add('spf_multiple', 'blocker', 'There are ' + d.spf_records.length + ' SPF records.',
    'Two SPF records cancel each other out: providers treat SPF as broken.',
    'Merge them into one record that starts with v=spf1.');
} else if (!spf && realMx.length) {
  add('spf_missing', 'blocker', 'No SPF record.',
    'People have mailboxes on this domain, but providers cannot tell which servers may send for it.',
    'Publish one TXT record on the domain that starts with v=spf1 and lists your sending services.');
} else if (!spf) {
  add('spf_not_at_this_name', 'note', 'No SPF record at this name.',
    'Normal for a subdomain run by an email tool: SPF is checked on the hidden return-path address, not on the visible From address.',
    'Open a real email from this domain and confirm the headers say spf=pass.');
} else {
  const all = spf.match(/(?:^|\s)([+\-~?]?)all(?:\s|$)/i);
  const redirects = /(?:^|\s)redirect=/i.test(spf);
  if (all && (all[1] === '+' || all[1] === '')) {
    add('spf_allows_everyone', 'blocker', 'SPF ends with +all.',
      'This authorises every server on the internet to send email as you.',
      'End the record with ~all or -all.');
  } else if ((all && all[1] === '?') || (!all && !redirects)) {
    add('spf_neutral', 'warning', 'SPF gives no verdict on unlisted servers (?all or no all).',
      'Providers get no guidance about servers that are not on your list.',
      'End the record with ~all, then -all once everything legitimate is listed.');
  }
  if (d.spf_lookups > 10) {
    add('spf_too_many_lookups', 'blocker', 'SPF needs ' + d.spf_lookups + ' DNS lookups; the limit is 10.',
      'Past 10 lookups SPF stops working, so providers treat your email as unauthenticated.',
      'Remove services you no longer use from the SPF record.');
  } else if (d.spf_lookups >= 9) {
    add('spf_near_lookup_limit', 'warning', 'SPF uses ' + d.spf_lookups + ' of the 10 DNS lookups allowed.',
      'One more email tool added to the record can break SPF for every message.',
      'Remove unused services before adding a new one.');
  }
  if (!d.spf_lookups_exact) {
    add('spf_count_is_minimum', 'note', 'Part of the SPF record could not be followed from outside.',
      'The lookup count shown is a minimum, not the exact figure.',
      'Nothing to fix; check the count with your DNS or email provider if it is close to 10.');
  }
}

// ---- DMARC: what providers should do with email that fails the checks ----
const dmarc = d.dmarc_records[0] || '';
const tag = (key) => ((dmarc.match(new RegExp('(?:^|;)\\s*' + key + '\\s*=\\s*([^;]+)', 'i')) || [])[1] || '').trim().toLowerCase();
let stage = 'missing';
if (d.dmarc_records.length > 1) {
  stage = 'invalid';
  add('dmarc_multiple', 'blocker', 'There are ' + d.dmarc_records.length + ' DMARC records.',
    'With more than one record providers ignore DMARC completely.',
    'Keep a single record at _dmarc.');
} else if (!dmarc && d.dmarc_other_txt.length) {
  stage = 'invalid';
  add('dmarc_not_a_policy', 'blocker',
    'A TXT record answers at ' + d.dmarc_name + ' but it is not a DMARC policy ("' + d.dmarc_other_txt[0].slice(0, 40) + '").',
    'A dashboard can show this as verified, yet providers find no policy. The usual cause is a wildcard record on a parked or misconfigured domain.',
    'Check you are working on the right domain, then publish a record that starts with v=DMARC1 at _dmarc.');
} else if (!dmarc) {
  add('dmarc_missing', 'blocker', 'No DMARC record.',
    'Nothing tells mailbox providers what to do with email that fakes your domain. Gmail, Yahoo and Outlook.com also require DMARC from bulk senders.',
    'Start with: v=DMARC1; p=none; rua=mailto:<an address you read>');
} else {
  const p = tag('p');
  const sp = tag('sp');
  const policy = d.dmarc_inherited && sp ? sp : p; // subdomains follow sp= when the organisation sets it
  stage = policy === 'reject' ? 'reject' : policy === 'quarantine' ? 'quarantine' : policy === 'none' ? 'monitoring' : 'invalid';
  if (stage === 'invalid') {
    add('dmarc_bad_policy', 'blocker', 'DMARC has no valid policy (p=' + (p || 'missing') + ').',
      'Providers ignore a DMARC record without a valid p= value.',
      'Set p=none, p=quarantine or p=reject.');
  }
  if (stage === 'monitoring') {
    add('dmarc_monitoring_only', 'warning', 'DMARC is in monitoring mode (p=none).',
      'Email that fakes your domain is still delivered: p=none only asks for reports.',
      'Read the reports for a few weeks, fix what fails, then move to p=quarantine and later p=reject.');
  }
  if (!tag('rua')) {
    if (stage === 'monitoring') {
      add('dmarc_no_reports', 'warning', 'DMARC has no report address (rua).',
        'Monitoring mode without a report address monitors nothing: nobody receives the reports.',
        'Add rua=mailto:<an address you read> to the record.');
    } else {
      add('dmarc_no_reports', 'note', 'DMARC has no report address (rua).',
        'You cannot see who sends as your domain or what gets blocked.',
        'Add rua=mailto:<an address you read> to the record.');
    }
  }
  if (!d.dmarc_inherited && sp === 'none' && (p === 'quarantine' || p === 'reject')) {
    add('dmarc_subdomains_open', 'warning', 'Subdomains are left out of the policy (sp=none).',
      'Fake email from any subdomain of yours is still delivered.',
      'Remove sp=none, or set sp to quarantine or reject.');
  }
  const pct = tag('pct');
  if (pct && Number(pct) < 100 && stage !== 'monitoring') {
    add('dmarc_partial', 'note', 'The policy applies to ' + pct + '% of failing email.',
      'The rest is delivered as if there were no policy.',
      'Raise pct to 100 once the reports are clean.');
  }
  if (d.dmarc_inherited) {
    add('dmarc_inherited', 'note', 'No DMARC record at this subdomain: the policy comes from ' + d.dmarc_name + '.',
      'That is how DMARC works for subdomains.',
      'Nothing to do unless this subdomain needs its own policy.');
  }
}

// ---- MX: can this domain receive replies and bounces ----
if (!realMx.length) {
  add('mx_missing', 'warning', 'This domain cannot receive email (no MX record).',
    'Replies and bounces sent to an address on this domain are lost.',
    'Use a From and Reply-To address on a domain that receives email, or add MX records.');
}

// ---- DKIM: the signature that proves a message was not altered ----
if (!d.dkim.length) {
  add('dkim_not_checked', 'note', 'DKIM was not checked: no selector is listed for this domain.',
    'A DKIM key cannot be found from outside without its selector name.',
    'Open a real email from this domain, find s= in the DKIM-Signature header and add it to dkim_selectors.');
}
for (const key of d.dkim) {
  if (!key.found) {
    add('dkim_selector_missing', 'blocker', 'No DKIM key at selector "' + key.selector + '".',
      'Messages signed with this selector fail DKIM, so DMARC can fail too.',
      'Publish the DKIM record your email tool gives you, or correct the selector name.');
  } else if (key.revoked) {
    add('dkim_key_revoked', 'blocker', 'The DKIM key at selector "' + key.selector + '" is empty (revoked).',
      'Messages signed with this selector fail DKIM.',
      'Publish the current key from your email tool.');
  }
}

// A failed lookup gives no verdict: it must never look like a missing record.
const has = (level) => findings.some((f) => f.level === level);
const status = d.lookup_errors.length ? 'ERROR' : has('blocker') ? 'FAIL' : has('warning') ? 'WARN' : 'PASS';

return {
  json: {
    domain: d.domain,
    label: d.label,
    status,
    dmarc_stage: d.lookup_errors.length ? 'unknown' : stage,
    findings: d.lookup_errors.length
      ? [{ code: 'lookup_failed', level: 'note', issue: 'DNS lookup failed (' + d.lookup_errors[0] + ').', plain: 'No verdict this run: the records could not be read.', fix: 'Nothing to do; the next run tries again.' }]
      : findings,
    spf,
    spf_lookups: d.spf_lookups,
    dmarc,
    dmarc_name: d.dmarc_name,
    mailbox_provider: mailbox,
    senders,
    other_includes: otherIncludes,
    dkim_checked: d.dkim.map((k) => k.selector),
    checked_at: d.checked_at,
  },
};

// Remembers each domain's last verdict in the workflow's own storage, so the alert fires only on change.
// ponytail: this memory lives in the n8n instance; move it to a sheet or database to share it across instances.
const store = $getWorkflowStaticData('global');
store.domains = store.domains || {};
const rank = { PASS: 0, WARN: 1, FAIL: 2 };

return $input.all().map(({ json: now }) => {
  const before = store.domains[now.domain];
  const print = JSON.stringify([now.status, now.findings.map((f) => f.code).sort(), now.spf, now.dmarc]);
  let change = 'same';
  if (now.status === 'ERROR') change = 'unknown'; // a failed lookup never overwrites the last verdict
  else if (!before) change = 'new';
  else if (before.print !== print) {
    change = rank[now.status] > rank[before.status] ? 'worse' : rank[now.status] < rank[before.status] ? 'better' : 'changed';
  }
  if (now.status !== 'ERROR') store.domains[now.domain] = { status: now.status, print };
  return { json: { ...now, change, previous_status: before ? before.status : null } };
});

// Writes two Slack messages: the digest of every domain, and an alert only for what needs attention now.
const rows = $input.all().map((item) => item.json);
const count = (status) => rows.filter((r) => r.status === status).length;
const icon = { FAIL: ':red_circle:', WARN: ':large_yellow_circle:', PASS: ':large_green_circle:', ERROR: ':white_circle:' };
const problems = (r) => r.findings.filter((f) => f.level !== 'note');

const digest = [
  '*Sender domain health* (' + new Date().toISOString().slice(0, 10) + '): ' + rows.length + ' domain' + (rows.length === 1 ? '' : 's') + ' checked',
  count('FAIL') + ' failing, ' + count('WARN') + ' with warnings, ' + count('PASS') + ' passing' + (count('ERROR') ? ', ' + count('ERROR') + ' not readable' : ''),
  ...rows.map((r) =>
    [icon[r.status] + ' *' + r.domain + '* ' + r.status + (r.label ? ' (' + r.label + ')' : '') + ' | DMARC: ' + r.dmarc_stage + ' | SPF lookups: ' + r.spf_lookups + '/10',
      ...(r.status === 'ERROR' ? r.findings : problems(r)).map((f) => '      - ' + f.issue),
    ].join('\n')),
].join('\n');

// Alert on: a domain that got worse, a first check that already fails, or records edited since the last run.
const urgent = rows.filter((r) => r.change === 'worse' || r.change === 'changed' || (r.change === 'new' && r.status === 'FAIL'));
const alert = urgent.map((r) => {
  const head = r.change === 'worse' ? 'went from ' + r.previous_status + ' to ' + r.status
    : r.change === 'changed' ? 'has different DNS records than last run (still ' + r.status + ')'
    : 'fails on its first check';
  return ['*' + r.domain + '* ' + head,
    ...problems(r).map((f) => '- ' + f.issue + '\n   _What it means:_ ' + f.plain + '\n   _Fix:_ ' + f.fix),
  ].join('\n');
}).join('\n\n');

return [{
  json: {
    digest,
    alert: alert ? ':rotating_light: *Sender domain alert*\n' + alert : '',
    needs_alert: urgent.length > 0,
    checked: rows.length,
    failing: count('FAIL'),
    warnings: count('WARN'),
    passing: count('PASS'),
    unreadable: count('ERROR'),
  },
}];
